-- Generated localized release notes.
local _, namespace = ...
namespace.releaseNotesByLocale = {["deDE"]={["sections"]={{["items"]={"Der Questtracker heißt jetzt Gruppen-Zielverfolgung (POT). Anzeigeeinstellungen und Fensterposition bleiben erhalten.","Öffne das Gruppenquestlog mit /qt pql. /qt compare funktioniert weiterhin als Alias; Hilfe und Tipps verwenden nun /qt pql.","Außerhalb einer Gruppe ausblenden ist im HUD-Bearbeitungsmodus und unter Einstellungen > Gruppen & Teilen > Gruppen-Zielverfolgung verfügbar. Beide Kontrollkästchen steuern dieselbe Einstellung. Bei neuen Profilen und beim Wiederherstellen der Standardwerte ist sie aktiviert; gespeicherte Einstellungen bleiben erhalten."},["title"]="Quests in der Gruppe"}},["version"]="7.4.3",["welcome"]="Klarere Namen und Einstellungen für Quests in der Gruppe."},["esES"]={["sections"]={{["items"]={"Seguimiento de misiones ahora se llama Seguimiento de objetivos del grupo (POT). Se conservan los ajustes de visualización y la posición de la ventana.","Usa /qt pql para abrir el registro de misiones del grupo. /qt compare sigue funcionando como alias; la ayuda y los consejos ahora usan /qt pql.","Ocultar cuando no estés en un grupo está disponible en el modo de edición del HUD y en Ajustes > Grupos y compartir > Seguimiento de objetivos del grupo. Ambas casillas controlan el mismo ajuste. Se activa en perfiles nuevos y al restablecer los valores predeterminados; se conservan las preferencias guardadas."},["title"]="Misiones en grupo"}},["version"]="7.4.3",["welcome"]="Nombres y controles más claros para las misiones en grupo."},["esMX"]={["sections"]={{["items"]={"Seguimiento de misiones ahora se llama Seguimiento de objetivos del grupo (POT). Se conservan los ajustes de visualización y la posición de la ventana.","Usa /qt pql para abrir el registro de misiones del grupo. /qt compare sigue funcionando como alias; la ayuda y los consejos ahora usan /qt pql.","Ocultar cuando no estés en un grupo está disponible en el modo de edición del HUD y en Configuración > Grupos y compartir > Seguimiento de objetivos del grupo. Ambas casillas controlan el mismo ajuste. Se activa en perfiles nuevos y al restablecer los valores predeterminados; se conservan las preferencias guardadas."},["title"]="Misiones en grupo"}},["version"]="7.4.3",["welcome"]="Nombres y controles más claros para las misiones en grupo."},["frFR"]={["sections"]={{["items"]={"Le suivi de quête devient le suivi des objectifs du groupe (POT). Les réglages d’affichage et la position de la fenêtre sont conservés.","Utilisez /qt pql pour ouvrir le journal de quêtes du groupe. /qt compare reste un alias ; l’aide et les conseils utilisent désormais /qt pql.","Le masquage hors groupe est disponible dans le mode Édition du HUD et dans Paramètres > Groupes et partage > Suivi des objectifs du groupe. Les deux cases contrôlent le même réglage. Il est activé pour les nouveaux profils et lors du rétablissement des valeurs par défaut ; les choix enregistrés sont conservés."},["title"]="Quêtes en groupe"}},["version"]="7.4.3",["welcome"]="Des noms et réglages plus clairs pour les quêtes en groupe."},["itIT"]={["sections"]={{["items"]={"Tracciamento missioni ora si chiama Tracciamento obiettivi del gruppo (POT). Le impostazioni di visualizzazione e la posizione della finestra vengono mantenute.","Usa /qt pql per aprire il registro missioni del gruppo. /qt compare continua a funzionare come alias; la guida e i suggerimenti ora usano /qt pql.","Nascondi quando non sei in gruppo è disponibile nella modalità Modifica HUD e in Impostazioni > Gruppi e condivisione > Tracciamento obiettivi del gruppo. Entrambe le caselle controllano la stessa impostazione. È attiva nei nuovi profili e dopo il ripristino dei valori predefiniti; le scelte salvate vengono mantenute."},["title"]="Missioni di gruppo"}},["version"]="7.4.3",["welcome"]="Nomi e controlli più chiari per le missioni di gruppo."},["koKR"]={["sections"]={{["items"]={"퀘스트 추적기의 이름이 파티 목표 추적기(POT)로 변경되었습니다. 기존 표시 설정과 창 위치는 유지됩니다.","/qt pql로 파티 퀘스트 목록을 여세요. /qt compare도 계속 사용할 수 있으며, 도움말과 팁은 이제 /qt pql을 안내합니다.","파티에 속하지 않을 때 숨기기를 HUD 편집 모드와 설정 > 그룹 및 공유 > 파티 목표 추적기에서 변경할 수 있습니다. 두 체크박스는 같은 설정을 제어합니다. 새 프로필과 기본값으로 초기화 시에는 켜지며, 기존에 저장한 선택은 유지됩니다."},["title"]="파티 퀘스트"}},["version"]="7.4.3",["welcome"]="파티 퀘스트 기능의 이름과 설정을 더 명확하게 다듬었습니다."},["ptBR"]={["sections"]={{["items"]={"O rastreador de missões agora se chama Rastreador de objetivos do grupo (POT). As configurações de exibição e a posição da janela são preservadas.","Use /qt pql para abrir o registro de missões do grupo. /qt compare continua funcionando como um alias; a ajuda e as dicas agora usam /qt pql.","Ocultar fora de um grupo está disponível no modo de edição do HUD e em Configurações > Grupos e compartilhamento > Rastreador de objetivos do grupo. As duas caixas controlam a mesma opção. Ela vem ativada em novos perfis e ao restaurar os padrões; as escolhas salvas são preservadas."},["title"]="Missões em grupo"}},["version"]="7.4.3",["welcome"]="Nomes e controles mais claros para missões em grupo."},["ruRU"]={["sections"]={{["items"]={"«Отслеживание заданий» теперь называется «Отслеживание целей группы» (POT). Настройки отображения и положение окна сохраняются.","Открывайте журнал заданий группы командой /qt pql. /qt compare по-прежнему работает как псевдоним; справка и подсказки теперь используют /qt pql.","Скрытие вне группы доступно в режиме редактирования HUD и в Настройки > Группы и обмен > Отслеживание целей группы. Оба флажка управляют одной настройкой. Она включена для новых профилей и при сбросе к значениям по умолчанию; сохранённые настройки остаются прежними."},["title"]="Задания в группе"}},["version"]="7.4.3",["welcome"]="Более понятные названия и настройки для заданий в группе."},["zhCN"]={["sections"]={{["items"]={"任务追踪器现已更名为小队目标追踪器（POT）。现有显示设置和窗口位置保持不变。","使用 /qt pql 打开队伍任务日志。/qt compare 仍可作为别名使用；帮助和提示现在使用 /qt pql。","现在可在 HUD 编辑模式和设置 > 小队与分享 > 小队目标追踪器中调整“不在小队时隐藏”。两个复选框控制同一个设置。新配置及恢复默认值时默认开启；现有已保存的选择保持不变。"},["title"]="小队任务"}},["version"]="7.4.3",["welcome"]="让小队任务功能的名称和设置更加清晰。"},["zhTW"]={["sections"]={{["items"]={"任務追蹤器現已更名為隊伍目標追蹤器（POT）。現有顯示設定和視窗位置保持不變。","使用 /qt pql 開啟隊伍任務日誌。/qt compare 仍可作為別名使用；說明和提示現在使用 /qt pql。","現在可在 HUD 編輯模式和設定 > 隊伍與分享 > 隊伍目標追蹤器中調整「不在隊伍時隱藏」。兩個核取方塊控制同一項設定。新設定檔及恢復預設值時預設開啟；現有已儲存的選擇保持不變。"},["title"]="隊伍任務"}},["version"]="7.4.3",["welcome"]="讓隊伍任務功能的名稱和設定更加清晰。"}}
